// Component contracts, published read-only next to the token schema.
//
// `spec/contracts/` (generated by `npm run gen:contracts`) is copied into the
// build at `docs/agent-native/contracts/`, so any agent can read
// https://www.escalatokens.com/docs/agent-native/contracts/index.json and then
// `<Key>.json`: Figma set + axes, code API, slots, every role consumed, story.
// Static files, no endpoint: there is no hosted MCP (deleted 2026-10-20) and
// none is rebuilt for this. Nothing is committed twice — the copy happens at
// build time (`vite.config.ts` → `publishContracts`). Lives in `scripts/`: it is Node code (fs), never part of the app bundle.

import { readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

export const CONTRACTS_PUBLIC_DIR = 'docs/agent-native/contracts'
export const CONTRACTS_PUBLIC_URL = `https://www.escalatokens.com/${CONTRACTS_PUBLIC_DIR}/index.json`

export interface ContractAsset {
  /** Path inside the build output, e.g. `docs/agent-native/contracts/Button.json`. */
  fileName: string
  source: string
}

/** Every contract file in `dir` (normally `spec/contracts`) as a build asset. */
export function contractAssets(dir: string): ContractAsset[] {
  return readdirSync(dir)
    .filter((f) => f.endsWith('.json'))
    .sort()
    .map((f) => ({ fileName: `${CONTRACTS_PUBLIC_DIR}/${f}`, source: readFileSync(join(dir, f), 'utf8') }))
}
